import {Component, OnInit} from '@angular/core';
import {ActivatedRoute, Router} from '@angular/router';
import {FormService} from '../service/form.service';
import {DraftPayment} from '../service/form-submission';
import {AppConstants} from '../constants/app.constants';
import {Title} from '@angular/platform-browser';

declare var $: any;

@Component({
    selector: 'app-payment-component',
    templateUrl: './payment.component.html',
    styleUrls: ['./payment.component.scss']
})
export class PaymentComponent implements OnInit {
    token = '';
    uuid = '';
    amount = 0;
    formTitle = '';
    reference = '';
    appId = '';
    payment = null;

    constructor(public route: ActivatedRoute,
                private formService: FormService,
                private router: Router,
                private titleService: Title) {
        this.route.queryParams
            .subscribe(params => {
                this.token = params.token;
            });
    }

    ngOnInit(): void {
        this.titleService.setTitle(AppConstants.TITLE_PREFIX + 'Betaling');
        this.getPaymentDetails();
    }

    public currencyFormat(): string {
        return (
            this.amount
                .toFixed(2) // always two decimal digits
                .replace('.', ',') // replace decimal point character with ,
                .replace(/(\d)(?=(\d{3})+(?!\d))/g, '$1.')
        ); // use . as a separator
    }

    public getPaymentDetails(): void {
        $('#overlay').fadeIn();
        this.formService.getPaymentDetails(this.token).subscribe(result => {
            $('#overlay').fadeOut();
            if (result){
                this.uuid = result.uuid;
                this.amount = result.amount;
                this.formTitle = result.formTitle;
                this.reference = result.appId + result.reference;
                this.appId = result.appId;
                this.payment = result.payment;
            }else{
                // nothing was found so redirect to error page
                this.router.navigateByUrl('error');
            }
        });
    }

    public doPayment(): void{
        const draftPayment: DraftPayment = this.constructDraftPayment();
        this.formService.draftPaymentUuid(draftPayment).subscribe(draftResult => {
            this.formService.doPayment(this.amount, this.uuid, this.reference, this.formTitle, true, this.payment);
        });
    }

    constructDraftPayment(): DraftPayment{
        const draftPayment: DraftPayment = new DraftPayment();
        draftPayment.amount = this.amount;
        draftPayment.uuid =  this.uuid;
        draftPayment.appId = this.appId;
        draftPayment.reference = this.reference;
        draftPayment.formTitle = this.formTitle;
        return draftPayment;
    }
}
